function renderSpots(){$('spot-count').textContent=`${spots.length} района`;$('spot-list').innerHTML=orderedSpots().map(s=>`<button class="spot-card ${selected===s.id?'selected':''}" data-spot="${s.id}" aria-label="${esc(s.name)} — подробнее" aria-pressed="${selected===s.id}"><div class="spot-card-head"><span class="spot-number">${s.number}</span><span class="spot-name">${s.name}</span></div><p>${s.summary}</p><div class="spot-meta"><span>${s.tag}</span><span>~${format(haversine([launch.lat,launch.lon],[s.lat,s.lon]))} км*</span></div></button>`).join('');$('spot-list').querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>selectSpot(b.dataset.spot,true))}
function selectSpot(id,details=false){const s=spots.find(s=>s.id===id);if(!s)throw Error('Неизвестный район');selected=id;renderSpots();for(const [key,marker]of markers)marker.setIcon(L.divIcon({className:`map-marker ${key===id?'selected':''}`,html:spots.find(p=>p.id===key).number,iconSize:[34,34],iconAnchor:[17,17]}));map.flyTo([s.lat,s.lon],13,{duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:.55});if(details)spotDetails(s);return s}
function spotDetails(s){modal(s.name,`<div class="highlight">${s[session]}</div><p>${s.description}</p><h3>Что проверить эхолотом</h3><p>${s.searchDepth}. Это <strong>начальный диапазон поиска, не измеренная глубина района</strong>. Фактическую глубину, горизонт рыбы и структуру дна определите на месте.</p><p>Сделайте 2–3 коротких прохода поперёк обнаруженного склона. Отметьте перепад и кормовую стаю; обловите верх, склон и низ. Если контактов нет за 20–30 минут, смените участок.</p><h3>Ориентир поиска</h3><p><strong>${s.lat.toFixed(4)}° N, ${s.lon.toFixed(4)}° E</strong><br>Радиус разведки около ${s.radius} м. Круг может пересекать берег: проверять только акваторию. Центр выбран автором плана по географии острова; наличие рыбы не подтверждено.</p><p class="form-help">* ~${format(haversine([launch.lat,launch.lon],[s.lat,s.lon]))} км по прямой от центра Байрамгулово. Это не длина пути по воде; точный спуск неизвестен.</p><a href="${s.source}" target="_blank" rel="noopener">Положение острова в OpenStreetMap ↗</a><div><button class="button" id="copy-coords">Копировать координаты</button><button class="button quiet" id="show-on-map">Вернуться к карте</button></div>`);$('copy-coords').onclick=async()=>{try{await navigator.clipboard.writeText(`${s.lat.toFixed(4)}, ${s.lon.toFixed(4)}`);toast('Координаты скопированы')}catch{toast('Можно выделить и скопировать координаты выше')}};$('show-on-map').onclick=()=>$('detail-dialog').close()}
function addRegions(){regions.clearLayers();markers.clear();for(const s of spots){L.circle([s.lat,s.lon],{radius:s.radius,color:'#c9ee83',weight:1.5,dashArray:'5 6',fillColor:'#b5db78',fillOpacity:.1}).addTo(regions).on('click',()=>selectSpot(s.id,true));const m=L.marker([s.lat,s.lon],{title:s.name,icon:L.divIcon({className:`map-marker ${selected===s.id?'selected':''}`,html:s.number,iconSize:[34,34],iconAnchor:[17,17]})}).addTo(regions).on('click',()=>selectSpot(s.id,true));markers.set(s.id,m)}L.marker([launch.lat,launch.lon],{title:'Байрамгулово — ориентир села, не слип',icon:L.divIcon({className:'launch-marker',html:'⌂',iconSize:[29,29]})}).addTo(regions).bindPopup(`<strong>Байрамгулово</strong>${launch.description}`).bindTooltip('Байрамгулово',{permanent:true,direction:'right',className:'place-label'})}
function setSession(id){if(!Object.hasOwn(SESSIONS,id))throw Error('Неизвестный выход');session=id;hour=SESSIONS[id].hour;const s=SESSIONS[id];$('hour-slider').min=s.min;$('hour-slider').max=s.max;$('hour-slider').value=hour;document.querySelectorAll('[data-session]').forEach(b=>{b.classList.toggle('active',b.dataset.session===id);b.setAttribute('aria-pressed',String(b.dataset.session===id))});selected='lipovy-east';renderSpots();renderWeather();renderSummary();addRegions()}
function renderSummary(){const s=SESSIONS[session];$('session-summary').innerHTML=session==='evening'?`<strong>${s.window} · закат в 19:05</strong>Днём найти перепад и кормовую рыбу. В сумерках проверить соседние мелкие площадки.`:`<strong>${s.window} · восход в 06:39</strong>Возможен туман. Возвращаться к найденным с вечера участкам после проверки видимости.`}
function visibility(v){return !finite(v)?'—':v<1000?`${Math.round(v)} <small>м</small>`:`${format(v/1000,v<5000?1:0)} <small>км</small>`}
