function renderWeather(){if(!weather)return;const s=SESSIONS[session],r=hourRow(weather,s.date,hour);if(!r)return;const pressure=pressureMode==='surface'?format(finite(r.surface_pressure)?r.surface_pressure*HPA_TO_MMHG:null):format(r.pressure_msl);const cells=[['ВОЗДУХ',`${format(r.temperature_2m)}°`,`Облака ${format(r.cloud_cover,0)}%`],['ВЕТЕР',`${format(r.wind_speed_10m)} <small>м/с</small>`,`${windDirection(r.wind_direction_10m)} · порывы ${format(r.wind_gusts_10m)}`],['ДАВЛЕНИЕ ↕',`${pressure} <small>${pressureMode==='surface'?'мм':'hPa'}</small>`,pressureMode==='surface'?'у поверхности модели':'на уровне моря'],['ОСАДКИ',`${format(r.precipitation)} <small>мм</small>`,`Вероятность ${format(r.precipitation_probability,0)}%`],['ВИДИМОСТЬ',visibility(r.visibility),'прогноз модели']];$('weather-strip').innerHTML=cells.map(([a,b,c],i)=>`<${i===2?'button':'div'} class="weather-cell${i===2?' pressure-toggle':''}" ${i===2?'id="pressure-toggle" aria-label="Переключить давление у поверхности и на уровне моря"':''}><span class="weather-label">${a}</span><div class="weather-value">${b}</div><div class="weather-sub">${c}</div></${i===2?'button':'div'}>`).join('');$('pressure-toggle').onclick=()=>{pressureMode=pressureMode==='surface'?'msl':'surface';renderWeather()};$('selected-hour').textContent=`${String(hour).padStart(2,'0')}:00`;$('forecast-title').textContent=`${s.name} · ${session==='evening'?'19':'20'} сентября`;$('weather-stamp').textContent=`Получен ${weatherStamp} · UTC+5`;
const times=[];for(let t=s.min;t<=s.max;t++)times.push(hourRow(weather,s.date,t));const fog=times.filter(t=>finite(t?.visibility)&&t.visibility<1000);$('weather-alert').innerHTML=session==='morning'&&fog.length?`<div class="weather-alert warning"><strong>Туман в утреннем окне.</strong> Модель даёт ${Math.round(Math.min(...fog.map(t=>t.visibility)))}–${Math.round(Math.max(...fog.map(t=>t.visibility)))} м видимости. Дальний переход отложите до улучшения фактической видимости.</div>`:`<div class="weather-alert">${session==='evening'?'Слабый ветер; главный ориентир поиска — сумерки.':'Проверьте видимость перед выходом. Температура и облачность различаются между моделями.'} MSL за 6 ч: ${sign(trend(weather,r.time,6))} hPa.</div>`;
const pressures=times.map(t=>t.pressure_msl),min=Math.min(...pressures)-.3,max=Math.max(...pressures)+.3,coords=times.map((t,i)=>`${80+i*(600/(times.length-1))},${55-(t.pressure_msl-min)/(max-min)*40}`).join(' '),rows=[['Воздух, °C',t=>format(t.temperature_2m)],['Ветер / порыв, м/с',t=>`${format(t.wind_speed_10m)} / ${format(t.wind_gusts_10m)}`],['Давление MSL, hPa',t=>format(t.pressure_msl)],['Видимость',t=>!finite(t.visibility)?'—':t.visibility<1000?`${Math.round(t.visibility)} м`:`${format(t.visibility/1000,t.visibility<5000?1:0)} км`]];
$('hourly-chart').innerHTML=`<svg class="pressure-chart" viewBox="0 0 730 72" role="img" aria-label="Давление MSL от ${format(pressures[0])} до ${format(pressures.at(-1))} hPa"><text x="0" y="21" fill="#a5b5bf" font-size="11">MSL, hPa</text><text x="0" y="41" fill="#c9ee83" font-size="12">${format(pressures[0])}</text><line x1="80" y1="55" x2="680" y2="55" stroke="#34454e"/><polyline points="${coords}" fill="none" stroke="#c9ee83" stroke-width="2.5"/>${times.map((t,i)=>`<circle cx="${80+i*600/(times.length-1)}" cy="${55-(t.pressure_msl-min)/(max-min)*40}" r="${s.min+i===hour?5:2}" fill="#c9ee83"/>`).join('')}<text x="683" y="18" fill="#c9ee83" font-size="11">${format(pressures.at(-1))}</text></svg><div class="chart-scroll"><table class="weather-table"><thead><tr><th scope="col">${s.sun}</th>${times.map((t,i)=>`<th scope="col" class="${s.min+i===hour?'current':''}">${String(s.min+i).padStart(2,'0')}:00</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${label}</th>${times.map((t,i)=>`<td class="${s.min+i===hour?'current':''}">${fn(t)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>setSession(b.dataset.session));$('hour-slider').oninput=e=>{hour=Number(e.target.value);renderWeather()};
$('refresh-weather').onclick=async()=>{const b=$('refresh-weather');b.disabled=true;b.textContent='Обновляем…';try{const response=await fetch(WEATHER_URL,{signal:AbortSignal.timeout(18000)});if(!response.ok)throw Error(`HTTP ${response.status}`);weather=validateWeather(await response.json());weatherStamp=new Intl.DateTimeFormat('ru-RU',{timeZone:'Asia/Yekaterinburg',dateStyle:'short',timeStyle:'short'}).format(new Date());store.set('argazi-weather-v1',{data:weather,stamp:weatherStamp});renderWeather();toast('Прогноз на оба выхода обновлён')}catch{toast(`Обновление недоступно. Сохранён прогноз от ${weatherStamp}; даты выхода не изменены.`)}finally{b.disabled=false;b.textContent='↻ Обновить'}};
