function renderDepths(){depthLayer.clearLayers();L.geoJSON(ownDepths,{pointToLayer:(f,ll)=>L.circleMarker(ll,{radius:5,color:'#cef3ff',fillColor:'#69bfdc',fillOpacity:1,weight:1.5}),style:{color:'#82d3e6',weight:2},onEachFeature:(f,l)=>{l.bindTooltip(`${format(f.properties.depth)} м`,{permanent:f.geometry.type==='Point',className:'depth-label',direction:'top'});const box=document.createElement('div'),p=document.createElement('p'),b=document.createElement('button');p.textContent=`Личный промер / загруженная изобата: ${format(f.properties.depth)} м. Не приведено к единому уровню воды.`;b.className='button';b.textContent='Удалить этот промер';b.onclick=()=>{const previous=ownDepths;saveDepths({type:'FeatureCollection',features:ownDepths.features.filter(x=>x!==f)});store.set('argazi-depth-backup-v1',previous);map.closePopup()};box.append(p,b);l.bindPopup(box)}}).addTo(depthLayer);$('depth-status').textContent=ownDepths.features.length?`Личные глубины: ${ownDepths.features.length} объектов`:'Изобаты не получены · см. «Глубины»'}
function saveDepths(fc){ownDepths=fc;const saved=store.set('argazi-depth-v1',fc);renderDepths();toast(saved?'Глубины сохранены в этом браузере. Сделайте экспорт для переноса.':'Браузер не сохранил данные. Выгрузите GeoJSON.')}
function depthDialog(){modal('Карта глубин',`<div class="highlight">Подтверждённого открытого слоя глубин Аргази не найдено. На основной карте — береговая линия и районы поиска; приблизительные изобаты не нарисованы.</div><h3>Доступные карты водохранилища</h3><p><a href="https://mapfish.ru/region/125" target="_blank" rel="noopener">MapFish — Аргазинское водохранилище ↗</a><br>Батиметрия требует Premium. Часть рельефа интерполирована; издатель не рекомендует использовать её для навигации.</p><p><a href="https://rybalka.mobilekarta.ru/ru/catalog/mapgallerylibrary/buy-depth-maps/dm_argazinskoe_01/" target="_blank" rel="noopener">Карта РУ Рыбалка — карта глубин Аргази ↗</a><br>Платная карта с частичным охватом. Просмотр и покупка в приложении издателя. Покупка карты не даёт права публиковать её здесь.</p><h3>Ваши промеры и изобаты</h3><p>Загрузите собственный CSV или GeoJSON. Данные останутся в этом браузере и не отправляются на сервер. Сейчас объектов: <strong>${ownDepths.features.length}</strong>.</p><label class="field">Файл глубин<input id="depth-file" type="file" accept=".csv,.json,.geojson"></label><p class="form-help">CSV: lat,lon,depth; разделитель запятая или точка с запятой. GeoJSON: Point, LineString или MultiLineString с числовым properties.depth. WGS84, метры, до 5 МБ. Новый файл добавится к текущему слою.</p><div id="import-result" role="status" aria-live="polite"></div><button class="button" id="export-depths">↓ Экспорт GeoJSON</button><button class="button quiet" id="manual-depth">Записать промер</button><h3>Как читать личный слой</h3><p>Числа у точек — ваши промеры; линии — импортированные изобаты. Между точками глубина не интерполируется. Учитывайте дату промера и изменение уровня водохранилища.</p>`);$('depth-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error('Максимум 5 МБ');const fc=parseDepthFile(await f.text(),f.name),existing=new Set(ownDepths.features.map(f=>JSON.stringify(f))),added=fc.features.filter(f=>!existing.has(JSON.stringify(f)));if(ownDepths.features.length+added.length>10000)throw Error('Суммарно не более 10 000 объектов');saveDepths({type:'FeatureCollection',features:[...ownDepths.features,...added]});$('import-result').textContent=`Добавлено объектов: ${added.length}. Закройте окно, чтобы посмотреть карту.`}catch(err){$('import-result').textContent=`Не удалось загрузить: ${err.message}`}};$('export-depths').onclick=()=>{if(!ownDepths.features.length){toast('Пока нет личных промеров для экспорта');return}download('argazi-my-depths.geojson',JSON.stringify(ownDepths,null,2))};$('manual-depth').onclick=()=>depthForm()}
$('depth-button').onclick=depthDialog;
function depthForm(ll){modal('Записать промер эхолота',`<p>Запишите фактическую глубину и координаты. Промер сохранится локально. Можно закрыть окно и нажать нужное место на карте.</p><form id="depth-form"><div class="input-grid"><label class="field">Широта, ° N<input name="lat" type="number" required min="55.27" max="55.58" step="0.000001" value="${ll?ll.lat.toFixed(6):''}" placeholder="55.390000"></label><label class="field">Долгота, ° E<input name="lon" type="number" required min="60.23" max="60.61" step="0.000001" value="${ll?ll.lng.toFixed(6):''}" placeholder="60.440000"></label></div><label class="field">Глубина по эхолоту, м<input name="depth" type="number" required min="0" max="50" step="0.1" placeholder="Фактический промер"></label><p class="form-help">Координаты WGS84. Уточните поправку от датчика до поверхности. Место клика на карте — приблизительный ориентир.</p><button class="button" type="submit">Сохранить промер</button><p id="depth-result" role="status"></p></form>`);$('depth-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),fc=parseDepthFile(JSON.stringify({type:'Feature',properties:{depth:Number(f.get('depth'))},geometry:{type:'Point',coordinates:[Number(f.get('lon')),Number(f.get('lat'))]}}),'point.geojson');if(ownDepths.features.length>=10000)throw Error('Достигнут предел 10 000 объектов');saveDepths({type:'FeatureCollection',features:[...ownDepths.features,...fc.features]});$('detail-dialog').close()}catch(err){$('depth-result').textContent=err.message}}}
map.on('click',e=>{if(!validCoord(e.latlng.lng,e.latlng.lat))return;const box=document.createElement('div'),title=document.createElement('strong'),b=document.createElement('button');title.textContent=`${e.latlng.lat.toFixed(5)}, ${e.latlng.lng.toFixed(5)}`;b.className='button';b.textContent='Записать промер';b.onclick=()=>{map.closePopup();depthForm(e.latlng)};box.append(title,b);L.popup().setLatLng(e.latlng).setContent(box).openOn(map)});
$('analysis-button').onclick=()=>{const r=hourRow(weather,SESSIONS[session].date,hour);modal('Погода и тактика поиска',`<h3>Давление: плавный рост</h3><p>В ${String(hour).padStart(2,'0')}:00: у поверхности модели ${format(r.surface_pressure*HPA_TO_MMHG)} мм рт. ст.; на уровне моря ${format(r.pressure_msl)} hPa. Изменение MSL за 6 часов: ${sign(trend(weather,r.time,6))} hPa, за 24 часа: ${sign(trend(weather,r.time,24))} hPa. Это погодный контекст, а не шкала клёва.</p><p>Давление у поверхности рассчитано для ячейки модели на высоте ${weather.elevation} м; это не показание барометра на лодке. Сравнивать синоптический тренд удобнее по MSL. Переключение — нажатием карточки давления.</p><h3>Освещённость и глубина</h3><p>Вечернее окно 18:00–20:30 охватывает закат 19:05. Утреннее 05:40–08:30 — восход 06:39. Телеметрия судака показывает сумеречные перемещения, но активность не равна поклёвкам. Это перенос наблюдений из других водоёмов, а не доказанная модель Аргази.</p><h3>Утренний туман</h3><p>В исходном прогнозе 20 сентября в 05–07 часов видимость 540–660 м; к 08:00 около 2 км. MET Norway также прогнозирует туман. Решение о выходе принимайте по фактической видимости.</p><h3>Где модели расходятся</h3><p>Утром Best Match даёт около +7 °C и 47–53% облаков, GFS — около +9 °C и 86–100% облаков. MET Norway в 06:00 даёт +8,2 °C. Слабый ветер, сухая погода и постепенный рост давления согласуются лучше. Эта проверка относится к исходным снимкам от 19.09, а не к последующим обновлениям.</p><h3>Что остаётся неизвестным</h3><p>Нет измерений температуры воды, кислорода, термоклина и текущей батиметрии. Температура воздуха не заменяет температуру воды. Если кормовая рыба стоит выше дна, проверьте её горизонт. Проценты клёва, влияние Луны и магнитных бурь не рассчитываются.</p><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Данные и определения Open-Meteo ↗</a>`)};
$('plan-button').onclick=()=>modal('План с выходом из Байрамгулово',`<h3>19 сентября · вечер</h3><ol><li><strong>16:00–18:00 — разведка.</strong> После выхода вне охранной зоны плотины начать с восточной стороны Липового. Несколько поперечных проходов, поиск кормовой рыбы и фактического перепада. Запасной район — западная сторона.</li><li><strong>18:00–20:30 — окно поиска.</strong> Обловить найденный свал и соседнюю мелкую площадку. Закат 19:05. Не расходовать эти часы на переходы по всем меткам.</li><li><strong>Возвращение.</strong> Путь и время возврата определить засветло, с учётом лодки и реальной видимости. GPX содержит районы, а не проходы между островами.</li></ol><h3>20 сентября · утро</h3><ol><li><strong>Проверить туман.</strong> При плохой видимости отложить переход. Окно 05:40–08:30 — ориентир освещённости, не рекомендация выйти в туман.</li><li><strong>После улучшения видимости</strong> вернуться на рабочую точку вечера. Для разведки рассмотреть восточную сторону Свинячьего; близость к старту зависит от точного места спуска.</li><li><strong>После восхода</strong> проверить нижнюю часть найденного перепада и горизонт кормовой рыбы. Вишнёвый оставить запасным районом при хорошей погоде и достаточном запасе времени.</li></ol><h3>Стартовый набор снастей</h3><p>Джиг и силикон 8–12 см; груз подбирать по фактической глубине, ветру и контролю дна. Начать со ступеньки и пауз, затем проверить медленную подачу. При корягах — незацепляющийся монтаж. Это исходная тактика для проверки, а не результат промеров.</p><h3>Правила на дату поездки</h3><p><strong>Судак от 35 см.</strong> Измерять от рыла при закрытом рте до основания средних лучей хвостового плавника. Судак, лещ, язь, щука, сазан, карась, плотва и окунь — <strong>суммарно до 5 кг в сутки на человека</strong>. Общая норма всей таблицы не увеличивает лимит этой группы. Весенний запрет 5 мая–15 июня к поездке не относится.</p><p>Охраняемую зону плотины в поиск не включаем; её фактические границы определяются местными знаками и режимом ГТС. Радиус запрета на карте не придуман. Для подъезда используйте разрешённые дороги и стоянки.</p><a href="https://fish.gov.ru/wp-content/uploads/2024/11/pravila_rybolovstva_dlya_zapadno_sibirskogo_rybohozyajstvennogo_bassejna.pdf" target="_blank" rel="noopener">Правила Росрыболовства, п. 15.2 и 36.1 ↗</a><br><a href="https://base.garant.ru/400453923/53f89421bbdaf741eb2d1ecc4ddb4c33/" target="_blank" rel="noopener">Сверка с редакцией от 08.09.2026 ↗</a>`);
$('sources-button').onclick=()=>modal('Источники и точность',`<h3>Что нанесено на карту</h3><p>Берега и острова — <a href="https://www.openstreetmap.org/relation/172936" target="_blank" rel="noopener">OpenStreetMap, relation 172936</a>, лицензия ODbL. Спутник — Esri World Imagery; дата съёмки может отличаться от даты поездки. Острова сверены по объектам OSM; ссылки — в карточках районов. Байрамгулово отмечено как населённый пункт, не как проверенный слип.</p><p>Круги и центры — авторские районы разведки около островов, радиус 550–650 м. Они не основаны на промерах или отчётах о поимках в эти даты. Метры в карточках — диапазоны, с которых можно начать поиск эхолотом, а не глубины в точках.</p><h3>Батиметрия</h3><p>Проверены <a href="https://mapfish.ru/region/125" target="_blank" rel="noopener">MapFish</a> и <a href="https://rybalka.mobilekarta.ru/ru/catalog/mapgallerylibrary/buy-depth-maps/dm_argazinskoe_01/" target="_blank" rel="noopener">Карта РУ</a>. Подробные карты требуют платного доступа. Открытого слоя с подтверждёнными глубинами и условиями переиспользования получить не удалось. Анализ конкретных бровок по батиметрии здесь не выполнен.</p><h3>Погода</h3><p><a href="https://open-meteo.com/en/docs" target="_blank" rel="noopener">Open-Meteo Best Match</a>, запрос 55,40° N / 60,42° E, UTC+5. Получен 19.09.2026 в 08:37 местного времени. Ячейка ответа: 55,4375 / 60,4375, высота 271 м. Конкретное имя модели API не сообщает.</p><p><a href="./data/weather.json" target="_blank">Исходный прогноз JSON</a> · <a href="./data/gfs.json" target="_blank">Проверка GFS</a> · <a href="./data/met-no.json" target="_blank">Проверка MET Norway</a>. MET Norway: выпуск 19.09 в 01:17 UTC. У моделей могут быть общие исходные данные. Обновление меняет только основной прогноз. Данные Open-Meteo и MET Norway — CC BY 4.0.</p><h3>Основания тактики</h3><p><a href="https://link.springer.com/article/10.1007/s10750-008-9503-0" target="_blank" rel="noopener">Horký et al., 2008</a>: сумеречные перемещения судака и глубины в Эльбе. <a href="https://doi.org/10.1007/s10750-004-6823-6" target="_blank" rel="noopener">Poulet et al., 2005</a>: вечерняя активность и индивидуальные различия. <a href="https://onlinelibrary.wiley.com/doi/abs/10.1111/eff.12619" target="_blank" rel="noopener">Westrelin et al., 2022</a>: роль стратификации и кислорода. Это не исследования Аргази.</p><h3>Без сети</h3><p>После первого полного открытия на GitHub Pages сохраняются интерфейс, контур берега, план и исходный прогноз. Онлайн-подложка и спутник без сети могут быть недоступны. Промеры хранятся только на этом устройстве; экспортируйте их отдельно. Геолокация включается по кнопке, не сохраняется и не отправляется приложением.</p><a href="https://github.com/ArtemiiPihalych/argazi-zander" target="_blank" rel="noopener">Репозиторий проекта ↗</a>`);
async function init(){try{const [raw,places,shore]=await Promise.all([fetch('./data/weather.json').then(r=>r.json()),fetch('./data/spots.json').then(r=>r.json()),fetch('./data/shoreline.geojson').then(r=>r.json())]);weather=validateWeather(raw);spots=places.spots;launch=places.launch;const saved=store.get('argazi-weather-v1');if(saved)try{weather=validateWeather(saved.data);weatherStamp=String(saved.stamp)}catch{}const depths=store.get('argazi-depth-v1');if(depths?.features?.length)try{ownDepths=parseDepthFile(JSON.stringify(depths),'saved.geojson')}catch{toast('Сохранённые промеры не прочитаны. Загрузите резервную копию.')}L.geoJSON(shore,{interactive:false,style:{color:'#528ca5',weight:1,fillColor:'#214857',fillOpacity:.72}}).addTo(shores);addRegions();renderSpots();renderSummary();renderWeather();renderDepths();map.fitBounds([[55.334,60.352],[55.434,60.516]],{padding:[32,70]});if('serviceWorker'in navigator&&location.hostname.endsWith('github.io'))navigator.serviceWorker.register('./sw.js').catch(()=>toast('Автономное сохранение недоступно; приложение работает с сетью.'));registerTools()}catch(err){$('weather-strip').textContent='Данные не загрузились. Обновите страницу с подключением к сети.';toast('Ошибка загрузки: '+err.message)}}
function registerTools(){if(!document.modelContext?.registerTool)return;const tools=[{name:'get_fishing_plan',description:'Read selected outing, forecast and authored search areas. Coordinates are not verified fish positions or safe routes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({session,hour,weather:hourRow(weather,SESSIONS[session].date,hour),areas:orderedSpots().map(s=>({id:s.id,name:s.name,lat:s.lat,lon:s.lon,radius:s.radius})),depthSource:ownDepths.features.length?'User imported, unverified':'No verified bathymetry'})},{name:'select_fishing_session',description:'Switch the visible plan to evening 19 September 2026 or morning 20 September 2026.',inputSchema:{type:'object',properties:{session:{type:'string',enum:['evening','morning']}},required:['session'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Object.hasOwn(SESSIONS,input.session))throw Error('Invalid session');setSession(input.session);return{session,hour}}}];for(const t of tools)try{Promise.resolve(document.modelContext.registerTool(t)).catch(()=>{})}catch{}}
await init();
